# ============================================================
# 4. CHOW STRUCTURAL BREAK — TALK FIGURE
# ============================================================
# Coalition dummy: 2010-2015 coalition inflated SPAD numbers (both Con + LibDem
# ministers had SPADs). In the dataset: coalition years = 2010, 2012, 2013.
# 2015 is post-majority (LibDem SPADs gone — explains the dip from 108 to 95).
# Model: n_spads ~ time + coalition_dummy (controls for coalition inflation).
# Chow tests whether there is a structural break in the underlying trend.
# Causal note (T-1): IV break should precede DV (turbulence) break at ~2014.

NAVY      <- "#1F3864"
RED       <- "#d7191c"
GREY_BLUE <- "#607D8B"
TALK_OUT  <- file.path(PROJECT, "figures/ch3_spads_chow_talk.png")

# Time index
d2 <- d |>
  mutate(
    t               = year - min(year),
    coalition_dummy = as.integer(year %in% c(2010, 2012, 2013))
  )

n_chow  <- nrow(d2)
p       <- 2   # intercept + slope (coalition always included as covariate)

# Restricted model (full sample, coalition controlled)
mod_r  <- lm(n_spads ~ t + coalition_dummy, data = d2)
RSS_r  <- sum(resid(mod_r)^2)

# Candidate break years: ≥ 3 obs each side
years_sorted     <- sort(d2$year)
candidate_breaks <- years_sorted[3:(length(years_sorted) - 3)]

chow_results <- do.call(rbind, lapply(candidate_breaks, function(k) {
  dat1 <- d2 |> filter(year <= k)
  dat2 <- d2 |> filter(year >  k)
  # Need ≥ 2 obs in each segment for lm to run
  if (nrow(dat1) < 3 || nrow(dat2) < 3) return(NULL)
  rss1 <- tryCatch(sum(resid(lm(n_spads ~ t + coalition_dummy, data = dat1))^2), error = function(e) NA)
  rss2 <- tryCatch(sum(resid(lm(n_spads ~ t + coalition_dummy, data = dat2))^2), error = function(e) NA)
  if (is.na(rss1) || is.na(rss2)) return(NULL)
  RSS_u  <- rss1 + rss2
  F_stat <- ((RSS_r - RSS_u) / p) / (RSS_u / (n_chow - 2 * p - 1))
  data.frame(break_year = k, F_stat = max(F_stat, 0),
             n1 = nrow(dat1), n2 = nrow(dat2))
}))

F_crit <- qf(0.95, df1 = p, df2 = n_chow - 2 * p - 1)
best_break <- chow_results$break_year[which.max(chow_results$F_stat)]
best_F     <- max(chow_results$F_stat)

cat(sprintf("\nChow (coalition-controlled): N=%d, critical F(%d,%d)=%.2f\n",
            n_chow, p, n_chow - 2*p - 1, F_crit))
cat("F-statistics:\n"); print(chow_results)
cat(sprintf("Data-preferred break: %d (F=%.2f)\n", best_break, best_F))

# --- Panel A: time series (no negative-y PM labels for patchwork compat) ---
p_series <- ggplot() +
  geom_rect(data = pm_bands,
