  annotate("text", x = 2012.5, y = 118,
           label = "Coalition\n(inflates\nSPADs)", size = 2.4,
           colour = "#888800", hjust = 0.5, lineheight = 0.9) +
  geom_line(data = d, aes(x = year, y = n_spads),
            colour = NAVY, linewidth = 0.9) +
  geom_point(data = d |> filter(!is_estimated),
             aes(x = year, y = n_spads), colour = NAVY, size = 2.5) +
  geom_point(data = d |> filter(is_estimated),
             aes(x = year, y = n_spads), colour = NAVY, size = 2.5, shape = 1) +
  scale_x_continuous(breaks = seq(1980, 2025, 5)) +
  scale_y_continuous(limits = c(0, 140), breaks = seq(0, 140, 20), expand = c(0,0)) +
  labs(
    title    = "A. SPADs in UK government, 1979–2025",
    subtitle = "Open circles = estimated. Yellow band = coalition 2010–15 (controls for LibDem SPAD inflation).",
    x = NULL, y = "Number of SPADs in post"
  ) +
  theme_bw(base_size = 11) +
  theme(
    plot.title       = element_text(face = "bold", colour = NAVY, size = 11),
    plot.subtitle    = element_text(colour = "#888888", size = 7.5),
    panel.grid.minor = element_blank(),
    panel.grid.major.x = element_blank(),
    axis.text.x      = element_text(angle = 45, hjust = 1)
  )

# --- Panel B: Chow F ---
p_chow <- ggplot(chow_results, aes(x = factor(break_year), y = F_stat)) +
  geom_col(fill = NAVY, width = 0.7) +
  geom_hline(yintercept = F_crit, linetype = "dashed",
             colour = RED, linewidth = 0.7) +
  annotate("text",
           x    = as.character(candidate_breaks[length(candidate_breaks)]),
           y    = F_crit + max(chow_results$F_stat) * 0.04,
           label = sprintf("Critical F(%d,%d) = %.2f (5%%)", p, n_chow-2*p-1, F_crit),
           hjust = 1, size = 2.5, colour = RED) +
  annotate("text",
           x    = as.character(best_break),
           y    = best_F + max(chow_results$F_stat) * 0.04,
           label = paste0("Peak:\n", best_break),
           hjust = 0.5, size = 2.5, colour = NAVY) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.12))) +
  labs(
    title    = "B. Chow structural break test (coalition-controlled)",
    subtitle = sprintf(
      "Model: SPADs ~ time + coalition_dummy. N=%d. Data-preferred break: %d (F=%.2f).\nBreak predates turbulence DV (~2014) — consistent with structural prior (T-1 logic).",
      n_chow, best_break, best_F),
    x = "Candidate break year", y = "Chow F-statistic"
  ) +
  theme_bw(base_size = 11) +
  theme(
    plot.title       = element_text(face = "bold", colour = NAVY, size = 11),
    plot.subtitle    = element_text(colour = "#888888", size = 7.5, lineheight = 1.2),
    panel.grid.minor = element_blank(),
    panel.grid.major.x = element_blank(),
    axis.text.x      = element_text(angle = 45, hjust = 1)
  )

p_talk <- p_series / p_chow +
  plot_layout(heights = c(2, 1)) +
  plot_annotation(
    caption = paste0(
      "Sources: Yong & Hazell (2014) pre-2010; Cabinet Office CSV 2010–2013; Annual Report on Special Advisers 2015–2022; Cabinet Office/IfG 2024–2025.\n",
      "Chow controls for coalition 2010–15 (LibDem SPAD inflation). King (1981): growth in SPADs = institutionalisation of career politician pipeline."
    ),
    theme = theme(plot.caption = element_text(size = 6.5, colour = "#888888", lineheight = 1.2))
  )

ggsave(TALK_OUT, p_talk, width = 10, height = 9, dpi = 300)
